import React from 'react';
import { Link } from 'react-router-dom';
// Asegúrate de que la ruta a tu logo es correcta. Usaré la que tenías dentro del componente.
// import logo from '../assets/Logo_GO.jpeg'; 

// El nombre del componente debe ser en PascalCase (HeaderLog)
const HeaderLog = () => {
    // Nota: Si el logo está en la carpeta 'public', puedes usar la ruta absoluta '/imagenes/Logo_GO.jpeg'
    // Si está importado, debes usar la variable 'logo'
    return (
        <header className="header-cliente">
            <nav>
                <div className="logo">
                    <Link to="/">
                        <img src="/imagenes/Logo_GO.jpeg" alt="Logo de Gurama" />
                    </Link>
                </div>
                <ul>
                    <li><Link to="/">Volver</Link></li>
                    <li><Link to="/registro">Registrarse</Link></li>
                </ul>
            </nav>
        </header>
    );
};

// Exportamos el componente con el nombre correcto
export default HeaderLog;
